SELECT FROM sys_permission
AND (permissionName LIKE CONCAT('%', #{keyword}, '%') OR permissionCode LIKE CONCAT('%', #{keyword}, '%') OR path LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort ASC, createTime ASC LIMIT #{offset}, #{size}

